contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to be able to call OpenToThePublic and AdjustBetAmounts as owner.
    // The test contract is the deployer/owner of C per problem statement, so this contract
    // can call owner-only functions on c.

    // The test takes amount equal to betLimit to send with wager() and a dummy difficulty.
    function run(uint256 betAmount, uint256 difficulty) public payable {
        require(address(this).balance >= betAmount);

        // Make contract open to public and set difficulty and bet limit to provided values.
        // These are owner-only; this contract deployed c so it is allowed.
        c.OpenToThePublic();
        c.AdjustBetAmounts(betAmount);
        c.AdjustDifficulty(difficulty);

        // Record balance before calling wager
        uint256 beforeBalance = address(c).balance;

        // Ensure we didn't already have a wager recorded for this address
        bool hadBefore = c.hasPlayerWagered(address(this));

        // Call wager sending betAmount. Catch revert to observe whether it succeeded.
        bool reverted;
        try c.wager{value: betAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        bool hasWager = c.hasPlayerWagered(address(this));

        // General property: if the wager call succeeded (did not revert) then
        // - hasPlayerWagered(address(this)) must be true afterwards,
        // - and the contract's balance must have increased by exactly betAmount.
        // If the call reverted, no guarantees about state changes are required.
        assert(reverted || (hasWager && afterBalance == beforeBalance + betAmount));
    }

    // Allow receiving ETH needed for the test harness
    receive() external payable {}
}

