        // We express: either reverted, or (afterTotalDonated == beforeTotalDonated + amount && beforeContractBalance >= afterContractBalance + amount)
        assert(reverted || (afterTotalDonated == beforeTotalDonated + amount && beforeContractBalance >= afterContractBalance + amount));
