    // params: whaleAddress unused here, but we take an address for open owner checks; amount to send as wager
    function run(address /*unused*/, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Precondition: ensure caller of owner-only functions is owner (contract deployer of c is owner),
        // but we are not owner. We will not call owner-only functions. Instead, we assume c was deployed with
        // betLimit set to amount so that wager() will accept the payment. To make the rule general, we first
        // read current betLimit and require amount equals it.
        uint256 beforeBetLimit = c.currentBetLimit();
        require(amount == beforeBetLimit);

        // Also require contract is open to public; since only owner can open, we try to open via a call and
        // catch revert: opening might revert because we're not owner. So we check if it's already open; if not,
        // we cannot proceed.
        // There is no getter for openToPublic, but trying to call wager will revert if not open; so first
        // check that calling wager with correct value succeeds (not reverted). We'll perform the wager then check effects.

        // Capture balances before
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempting wager, read observable state
        uint256 afterBalance = address(c).balance;
        bool hasWagered = c.hasPlayerWagered(address(this));

        // General rule: if wager call did not revert then contract balance increased by amount and hasPlayerWagered is true;
        // if it reverted then neither condition must hold (we assert the implication form)
        assert(reverted ? (afterBalance == beforeBalance && !hasWagered) : (afterBalance == beforeBalance + amount && hasWagered));
    }
}

