        c.AdjustBetAmounts(wagerLimit);
        c.AdjustDifficulty(diff);
        c.OpenToThePublic();

        // Record before-values
        uint256 beforeBalance = address(c).balance;

        // Place a wager by sending exactly the bet limit. If we don't have enough funds, still call with 0 to avoid nesting.
        // We ensure the call is a top-level statement by always executing a state-changing call; choose between two calls
