        // sequentially but only the one with matching value has effect according to C's require.
        // First, attempt a zero-value call which will revert inside C if betLimit != 0; we catch it.
        bool wagerZeroReverted;
        try c.wager{value: 0}() {
            wagerZeroReverted = false;
        } catch {
            wagerZeroReverted = true;
        }

        // Now, attempt to place the real wager if we have enough funds (top-level call).
        bool wagerRealReverted;
        if (fund >= wagerLimit) {
            try c.wager{value: wagerLimit}() {
                wagerRealReverted = false;
            } catch {
                wagerRealReverted = true;
            }
        } else {
            // If insufficient funds, mark as reverted (we did not call wager with value)
            wagerRealReverted = true;
        }

        // Call play() and observe whether it reverts. Top-level try/catch.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Read after-values
        uint256 afterBalance = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));

        // General property: if play did not revert, then the caller must no longer have an active wager
        // and the contract balance must not have increased compared to before calling play().
        assert(playReverted || (afterHas == false && afterBalance <= beforeBalance));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll drive the contract: open public, adjust difficulty and bet limit, place a wager from this contract,
    // then advance block by relying on the requirement that timestamp (block number) saved at wager < block.number
    // To simulate being a real player, calls are from this contract (msg.sender == tx.origin holds here).

    function run(address whaleAddr, uint256 initialBetLimit, uint256 difficulty, uint256 amount) public payable {
        require(amount == initialBetLimit, "amount must match bet limit to wager");
        // open to public
        c.OpenToThePublic();
        // set bet limit and difficulty
        c.AdjustBetAmounts(initialBetLimit);
        c.AdjustDifficulty(difficulty);

        // ensure this contract has enough balance to send the wager
        require(address(this).balance >= amount, "insufficient balance for wager");

        // read balances/observables before actions
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeWinnersPot = c.winnersPot();
        bool hadWagerBefore = c.hasPlayerWagered(address(this));

        // place wager: must equal bet limit
        c.wager{value: amount}();

        // After wager, timestamp recorded equals current block.number. To allow play() to proceed,
        // we need timestamps[msg.sender] < block.number. We cannot advance block in a single tx,
        // but the contract's play() requires the saved timestamp < block.number. The saved timestamp is the block
        // number at the wager call; calling play in the same transaction would revert. To reach the assert and
        // still test play's behavior, we detect that play would revert in this same tx, and require that when
        // it would not revert (i.e., when timestamp < block.number in some future call), the property holds.

        // Try calling play and catch whether it reverts
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observables after attempted play
        uint256 afterContractBalance = address(c).balance;
        uint256 afterWinnersPot = c.winnersPot();
        bool hasWagerAfter = c.hasPlayerWagered(address(this));

        // The general rule we assert:
        // If play() reverted, then state must be unchanged w.r.t. wager presence and contract balance (since play reverted),
        // except that wager() itself did change state (so hadWagerBefore must be false and hasWagerAfter true and balance increased by amount).
        // If play() did not revert (meaning timestamp < block.number), then after play the player's wager record is cleared
        // (hasPlayerWagered == false), and the contract's winnersPot either decreased by betLimit/2 (loss) or was paid out half
        // of contract balance (win). We express this as: if not reverted then hasWagerAfter==false and either
        // afterContractBalance + (afterWinnersPot) * 1 == afterContractBalance (trivially true) OR more usefully we check
        // that either the contract balance decreased by at least betLimit/2 (loss case) or the contract balance decreased by beforeWinnersPot (win case).

        uint256 betLimitObserved = c.currentBetLimit();

        // Compose the asserted invariant
        assert(
            // wager took effect: after wager the contract balance increased by amount and hasPlayerWagered became true
            (afterContractBalance == beforeContractBalance + amount && hasWagerAfter && !hadWagerBefore)
            // and, depending on play revert flag:
            && (
                reverted
                // if play reverted, nothing more required about cleared wager (it may remain set because play didn't run)
                || (
                    // if play did not revert then player's wager must be cleared
                    (!reverted && hasWagerAfter == false && (
                        // and either contract lost betLimit/2 (loss path) or lost at least beforeWinnersPot (win path)
                        // We conservatively require contract balance after play is <= beforeContractBalance + amount &&
                        // that it decreased by at least betLimit/2 when compared to balance right after wager.
                        (afterContractBalance + (betLimitObserved / 2) <= beforeContractBalance + amount) ||
                        (afterContractBalance + beforeWinnersPot <= beforeContractBalance + amount)
                    ))
                )
            )
        );
    }

    // allow receiving Ether for payouts/donations
    receive() external payable {}
}

contract InvMutTest {
