    // We take amount as input which we'll use to call wager{value: amount}()
    // The rule: if we open the contract, set betLimit to `amount`, and then call wager{value: amount}(),
    // that wager call succeeds (doesn't revert) and causes address(c).balance to increase by amount and
    // hasPlayerWagered(address(this)) to become true. Further, because wager records the current block number
    // as the timestamp, an immediate call to play() in the same transaction must revert (timestamp == block.number).
    function run(address whaleAddr, uint256 amount) public payable {
        // require we have the Ether available to send the wager
        require(address(this).balance >= amount);

        // Make the contract open and set bet limit to amount. Since this InvMutTest deployed c, it is the owner.
        c.OpenToThePublic();
        c.AdjustBetAmounts(amount);

        // Read observables before wagering
        uint256 beforeBalance = address(c).balance;
        bool hadWagerBefore = c.hasPlayerWagered(address(this));

