        c.wager{value: amount}();

        // After wager, read observables
        uint256 afterBalance = address(c).balance;
        bool hasWagerAfter = c.hasPlayerWagered(address(this));

        // Try calling play immediately; it should revert because wager stored timestamp == block.number
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Assert the general rule described above
        assert(
            // wager caused balance to increase exactly by amount and the wager flag to flip from false to true
            (afterBalance == beforeBalance + amount && hasWagerAfter == true && hadWagerBefore == false)
            // and an immediate play() in the same transaction must revert because timestamp == block.number
            && playReverted
        );
    }

